@@ -0,0 +1,93 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { t } from "../src/i18n/messages.js";
+import { app, auth, fresh, NOW } from "./helpers.js";
+
+test("missing or unknown key returns 401 unauthorized", async () => {
+  const { handle } = app();
+  for (const headers of [{}, { Authorization: "Basic abc" }, { Authorization: "Bearer " }, { Authorization: "Bearer nope" }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message.length > 0);
+  }
+  const notFoundUnauth = await handle({ path: "/nope" });
+  assert.equal(notFoundUnauth.status, 401);
+  assert.equal(notFoundUnauth.body.error.code, "unauthorized");
+});
+
+test("viewer can only read GET routes (except /audit)", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: auth("viewer") })).status, 200);
+  for (const req of [
+    { method: "POST", path: "/recipes/1/cook", body: { portions: 1 } },
+    { method: "POST", path: "/batches/1/waste", body: { qty: 1 } },
+    { method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: auth("viewer") });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("cook can cook, record waste, log temperatures and enter stock-take counts", async () => {
+  const { handle } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: auth("manager"), body: { location: "dry" } })).body;
+
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: auth("cook"), body: { qty: 0.5, reason: "trim" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: auth("cook"), body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: auth("cook"), body: { batchId: 6, counted: 12 } })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+    { method: "POST", path: "/prices", body: { supplierId: 1, itemId: 1, priceCents: 200, validFrom: "2026-10-28" } },
+    { method: "POST", path: "/dishes", body: { name: "Soup", recipeId: 1, priceCents: 900 } },
+    { method: "POST", path: "/jobs/nightly" },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: auth("cook") });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("data-changing requests write audit entries and GET /audit lists newest first", async () => {
+  let tick = NOW;
+  const store = fresh();
+  const handle = createApp(store, { clock: () => tick });
+
+  await handle({ path: "/items", headers: auth("viewer") });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: auth("cook"), body: { portions: 100 } });
+  await handle({ method: "POST", path: "/orders", headers: auth("cook"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } });
+
+  await handle({ method: "POST", path: "/batches/1/waste", headers: auth("cook"), body: { qty: 0.5, reason: "spill" } });
+  tick += 1000;
+  await handle({ method: "POST", path: "/orders", headers: auth("manager"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } });
+
+  const auditRes = await handle({ path: "/audit", headers: auth("manager") });
+  assert.equal(auditRes.status, 200);
+  assert.equal(auditRes.body.length, 2);
+  assert.deepEqual(
+    auditRes.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "manager", method: "POST", path: "/orders", status: 201 },
+      { keyName: "cook", method: "POST", path: "/batches/1/waste", status: 201 },
+    ],
+  );
+  assert.equal(auditRes.body[0].at, new Date(NOW + 1000).toISOString());
+  assert.equal(auditRes.body[1].at, new Date(NOW).toISOString());
+});
+
+test("auth error messages exist in English and Korean", () => {
+  for (const lang of ["en", "ko"]) {
+    assert.notEqual(t("unauthorized", lang), "unauthorized");
+    assert.notEqual(t("forbidden", lang), "forbidden");
+  }
+});
